INSERT INTO events (event_id, organizer_email, title, description, category, venue_name, start_time, end_time, star_points_eligible, images, created_at) VALUES
(1, 'josa_organizer@live.iium.edu.my', 'Jom Main Tradisi (Jauhar Week 2026)', 'Experience traditional games at Jauhar Week 2026! Organized by IIUM Johor Students Association (IIUM JOSA) in collaboration with Yayasan Pelajaran Johor & Maju Johor. Refreshments and Star Points provided for all participants.', 'Cultural & Sports', 'Mahallah Ali Field, IIUM Gombak', '2026-10-18 08:30:00', '2026-10-18 13:00:00', 1, '["E101","E102","E103"]', '2026-10-16 11:22:08'),
(2, 'pembina_organizer@live.iium.edu.my', 'Kickstart Your Campus Life: Smart Brain, Strong Soul', 'Join us for an inspiring session featuring Ammar bin Badrulhisham (Best Student Award Co-Curricular, Kulliyyah of Engineering) and Nur Irdina Hakimah binti NorAzali (PhD Candidate in Usul at-Din and Comparative Religion and Philosophy). Organized by Pembina IIUM Chapter (@pembina.uiam).', 'Academic & Talk', 'Experimental Hall, IIUM Gombak', '2026-10-18 20:00:00', '2026-10-18 22:30:00', 1, '["E201","E202","E203","E204"]', '2026-10-16 11:23:39'),
(3, 'titianasli_organizer@live.iium.edu.my', 'Tee Me Up! T-Shirt Design Competition', 'DON''T JUST WEAR IT. DESIGN IT. OWN IT! Tee Me Up! is your canvas to show your creativity. Theme: Health & Wellbeing (Ocean / Dreamy). Prizes: 1st Place (RM120 Cash + T-Shirt), 2nd Place (RM80 Cash), 3rd Place (RM50 Cash). Star points & E-Certificate provided! Organized by Titian Asli Club in collaboration with CENSERVE and IIUM.', 'Arts & Competition', 'Online Submission / IIUM Gombak', '2026-10-18 09:00:00', '2026-10-31 23:59:00', 1, '["E301"]', '2026-10-16 14:23:40'),
(4, 'odrsdce_organizer@live.iium.edu.my', 'Program Mahasiswa Negara Siri 6/2026', 'Invitation to all First-Year and Second-Year students for the 2025/2026 academic session at IIUM Gombak campus. The main objective of this programme is to foster a spirit of patriotism and strengthen national identity through nation-building activities. Organized by the Office of the Deputy Rector (Student Development & Community Engagement) - ODRSDCE. Contact: Br. Ahmad ''Izzuddin Yunus (03-6421 5997 / ahmadizzuddin@iium.edu.my).', 'Leadership & Development', 'PLK Ulu Sepri, Negeri Sembilan', '2026-10-18 08:00:00', '2026-10-20 17:00:00', 1, '["E401","E402","E403"]', '2026-10-16 14:26:46'),
(5, 'byic_organizer@live.iium.edu.my', 'BYIC FESTIVAL 2026: Opening Ceremony & Young Investor Empowerment Forum', 'BYIC FESTIVAL 2026 Opening Ceremony officiated by Pn. Mazliana (Director of Social Impact & Investor Empowerment, Bursa Malaysia), followed by the Young Investor Empowerment Forum: "Buy Now, Pay Later, Invest Later?". Panelists: Mdm. Noorsuriani Muhamed (Acting Director, Islamic Capital Market Bursa Malaysia), Mr. Khairi Shahrin Arief (CEO, CGS International Securities Malaysia), Br. Eyzzul Helmi (Grand Champion, ASEAN Investment Challenge 2025). Moderator: Dr. Fatimah Noor Rashidah (Assistant Professor, Department of Finance IIUM Gombak). Star points & excuse letter provided. Powered by Bursa Malaysia & Bursa Young Investor Club.', 'Forum & Finance', 'Main Auditorium, KOE, IIUM Gombak', '2026-10-29 09:00:00', '2026-10-29 13:00:00', 1, '["E501","E502"]', '2026-10-16 14:31:46'),
(6, 'byic_malamgalau@live.iium.edu.my', 'BYIC FESTIVAL 2026: Malam Galau (Closing Ceremony)', 'Ready to sing your heart out and vibe with the best beats? Join us for Malam Galau, the grand closing ceremony highlight of BYIC Festival 2026! Featuring Special Guest Artist Aziz Harun (Singer and Song Writer) and Opening Act IIUM Citra Band. Organized by Bursa Young Investor Club (BYIC 25/26) and Powered by Bursa Malaysia.', 'Entertainment & Concert', 'MPH KICT, IIUM Gombak', '2026-11-01 20:00:00', '2026-11-01 23:00:00', 0, '["E601","E602","E603"]', '2026-10-16 14:37:17'),
(7, 'integrity_organizer@live.iium.edu.my', 'IIUM Integrity Week 2026: The Ethical Lens', 'Empowering Integrity, Zero Tolerance Toward Corruption. Panelists: Timbalan Pesuruhjaya Mohd Azwan bin Ramli (Director of MACC Selangor), Assoc. Prof. Dr. Syaza Farhana Binti Mohamad Shukri (Associate Professor in Political Science at IIUM), Firdaus Husni (Director of Human Rights Strategist at MCCHR), Dr. Amir Mat Angsar (Retired Sergeant of PDRM). Star points and CTD provided.', 'Academic & Forum', 'Wadi Budi, IIUM Gombak', '2026-10-14 08:00:00', '2026-10-14 16:00:00', 1, '["E701","E702","E703"]', '2026-10-16 14:40:51'),
(8, 'iheal_organizer@live.iium.edu.my', 'i-HEAL 2026: Comic Competition', 'Create for Mental Health: A story can change a perspective. Theme: Unfolding The Self. Prizes: 1st Place (RM200), 2nd Place (RM100), 3rd Place (RM80), Consolation Prize (RM60). Organized as an official competition of i-HEAL IIUM National Counselling Month by ODRSDCE, IIUM Counselling and Career Services Centre (CCSC), and PEERS IIUM in collaboration with FLIC, Dar al-Hikmah Library, PKD, and KPJ Healthcare.', 'Arts & Competition', 'Online Submission / IIUM Gombak', '2026-10-12 00:00:00', '2026-10-19 23:59:00', 1, '["E801"]', '2026-10-16 14:44:46'),
(9, 'iheal_poetry@live.iium.edu.my', 'i-HEAL 2026: Poetry Competition', 'Create for Mental Health: Write it. Feel it. Share it. Theme: Unfolding The Self. Prizes: 1st Place (RM200), 2nd Place (RM100), 3rd Place (RM80), Consolation Prize (RM60). Organized as an official competition of i-HEAL IIUM National Counselling Month by ODRSDCE, IIUM Counselling and Career Services Centre (CCSC), and PEERS IIUM in collaboration with FLIC, Dar al-Hikmah Library, PKD, and KPJ Healthcare.', 'Arts & Competition', 'Online Submission / IIUM Gombak', '2026-10-12 00:00:00', '2026-10-19 23:59:00', 1, '["E901"]', '2026-10-16 14:49:48'),
(10, 'harum_serantau@live.iium.edu.my', 'Open Water Diving Course 2026', 'Join our 4 Days 3 Nights Open Water Diving Course in collaboration with Harum Serantau Biyad Centre & SDI. Receive SDI Open-Water Diver Certificate upon completion. What is included: 6 Dives, Fullboard Meals, Equipment Rental, Instructor Fees, Boat Transfer, and Triple/Quad Sharing Room. Excludes Marine Park & Jetty fees (RM10). Fee: RM1450/person (RM200 deposit). Limited to 15 PAX.', 'Sports & Outdoor', 'Perhentian Island, Malaysia', '2026-09-24 00:00:00', '2026-09-27 23:59:00', 1, '["E1001","E1002","E1003","E1004"]', '2026-10-16 21:48:29'),
(11, 'cuepacscare@live.iium.edu.my', 'Taklimat & Kaunter myCUEPACSCare IIUM Kuantan', 'Program Taklimat & Opening Kaunter myCUEPACSCare dengan harga istimewa untuk Kakitangan Universiti Awam Malaysia. Sesi Taklimat: 9.00 pagi - 11.00 pagi. Masa Kaunter: 11.00 pagi - 4.00 petang. Sila bawa bersama salinan MyKad & Slip Gaji terkini untuk pendaftaran. Pakej Perlindungan termasuk CUEPACSCare (Pelan Individu RM32/bln, Pelan Keluarga RM85/bln) dan CUEPACSPA (Pelan A RM6/bln, Pelan B RM12/bln).', 'Briefing & Expo', 'Banquet Hall, OCD, IIUM Kuantan', '2026-09-11 09:00:00', '2026-09-11 16:00:00', 0, '["E1101","E1102","E1103"]', '2026-10-16 21:50:21'),
(12, 'masjidshas_kuantan@live.iium.edu.my', 'Run For Faith 5KM Run 2026', 'Join the Run For Faith 5KM Run organized by Masjid SHAS, IIUM Kuantan. Schedule: 6:45 AM Briefing & Warm Up, 7:30 AM Flag Off. Packages: Package A (RM45 - T-shirt, Race Bib, Finisher Medal), Package B (RM35 - T-shirt & Race Bib). Includes refreshments and lucky draw. Top 3 prizes for IIUM Student (Male & Female) and Open (Male & Female) categories. Contact: 011-5804 1449 (Masjid SHAS) / 013-694 2205 (Br Amir).', 'Sports & Fitness', 'Masjid SHAS, IIUM Kuantan', '2026-10-03 06:45:00', '2026-10-03 11:00:00', 1, '["E1201","E1202","E1203"]', '2026-10-16 21:52:43');
INSERT INTO items (item_id, provider_email, title, description, item_type, category, price, price_unit, location_coverage, images, is_available, created_at) VALUES
(1, 'picnic_provider@live.iium.edu.my', 'Large Brown Checked Picnic Mat', 'Foldable and portable picnic mat with carry handle. Size: 200 x 200 cm. Ideal for campus picnics, outdoor gatherings, and recreational events.', 'rent', 'Outdoor & Recreation', 7.00, 'per_day', 'IIUM Kuantan Campus', '["R101"]', 1, '2026-10-16 15:57:25'),
(2, 'music_rentals@live.iium.edu.my', 'Portable 88-Key Keyboard Piano', '88 full-size keys with touch and velocity sensitivity, built-in stereo speakers, built-in sustain function, and multiple sounds/learning modes. Lightweight and portable design. Includes carry bag and power adapter.', 'rent', 'Music & Electronics', 45.00, 'per_day', 'IIUM Gombak Campus', '["R201"]', 1, '2026-10-16 15:58:57'),
(3, 'anytime_rentals@live.iium.edu.my', 'Anytime Fitness Keyfob Rental Service', 'Rent a keyfob for full 24/7 access to Anytime Fitness facilities. Safe, quick entry, perfect for students, travellers, or short-term members. DM to check availability and rental details.', 'rent', 'Sports & Health', 15.00, 'per_day', 'IIUM Gombak & Nearby Branches', '["R301"]', 1, '2026-10-16 16:01:57'),
(4, 'car_rentals@live.iium.edu.my', 'Perodua Axia (Dark Grey / Granite Grey)', 'Compact 5-seater hatchback available for daily or weekend rental around IIUM Gombak campus. Clean condition, cold AC, and fuel efficient. Perfect for short road trips and daily errands.', 'rent', 'Vehicles & Transport', 80.00, 'per_day', 'IIUM Gombak Campus', '["R401"]', 1, '2026-10-16 16:09:35'),
(5, 'sports_rentals@live.iium.edu.my', 'Nike Tiempo Football / Futsal Boots', 'White and grey Nike Tiempo leather football boots with original tag intact. Excellent grip, lightweight, and durable leather upper. Great for campus matches and football practice.', 'rent', 'Sports & Health', 10.00, 'per_day', 'IIUM Kuantan Campus', '["R501"]', 1, '2026-10-16 16:12:40'),
(6, 'gaming_rentals@live.iium.edu.my', 'Nintendo Switch V1 Console Set', 'Package includes Nintendo Switch v1 console, 1 pair Joy-Con Controllers, TV Dock, HDMI Cable, and original charger. Includes games (It Takes Two, Super Mario Party, Nintendo Switch Sports, Overcooked 2, and more). Add-on extra Joy-Cons available for RM25.', 'rent', 'Gaming & Gadgets', 50.00, 'per_day', 'IIUM Gombak Campus', '["R601"]', 1, '2026-10-16 16:14:06'),
(7, 'tech_rentals@live.iium.edu.my', 'Mechanical Keyboard with Rotary Knob (White/Pink/Grey)', '75% compact mechanical keyboard featuring custom white, pink, and grey keycaps, rotary volume knob, and tactile switches. Ideal for comfortable typing, study assignments, and gaming sessions.', 'rent', 'Gaming & Gadgets', 8.00, 'per_day', 'IIUM Pagoh Campus', '["R701"]', 1, '2026-10-16 16:15:58'),
(8, 'motor_rentals@live.iium.edu.my', 'Modenas Kriss 110 Motorcycle (Green)', 'Fuel-efficient Modenas Kriss 110 moped (Plate: VBT 4306) available for daily campus commute and short trips around Gombak. Includes helmet and lock.', 'rent', 'Vehicles & Transport', 25.00, 'per_day', 'IIUM Pagoh Campus', '["R801"]', 1, '2026-10-16 16:23:04'),
(9, 'motor_rentals@live.iium.edu.my', 'Slim White Electric Tower Fan', 'Space-saving vertical tower fan in clean white finish. Features quiet operation, multiple speed settings, and wide oscillation to keep your room or study space cool. Perfect for Mahallah rooms.', 'rent', 'Home Appliances', 5.00, 'per_day', 'IIUM Pagoh Campus', '["R901"]', 1, '2026-10-16 16:24:44'),
(10, 'photo_studio@live.iium.edu.my', 'Professional Campus Photography Service', 'High-quality photography services for IIUM club programmes, convocation portraits, outdoor photoshoots, and formal campus events. Fully edited high-resolution photos provided via Cloud link.', 'service', 'Media & Events', 50.00, 'per_hour', 'IIUM Kuantan Campus', '["S1001"]', 1, '2026-10-16 20:01:01'),
(11, 'photo_studio@live.iium.edu.my', 'Professional Video Editing Services', 'Cinematic video editing for promotional videos, event highlights, and documentaries. Turning your vision into reality with smooth storytelling and captivating visuals.', 'service', 'Media & Events', 40.00, 'per_item', 'IIUM Kuantan Campus', '["S1101"]', 1, '2026-10-16 20:03:26'),
(12, 'vehicles@live.iium.edu.my', 'Afternoon Campus Carpool Service', 'Reliable afternoon carpool rides for IIUM students and staff. Daily routes covering campus Mahallahs, local transit hubs (LRT Gombak), and nearby residential areas.', 'service', 'Transport', 5.00, 'per_trip', 'IIUM Gombak & Surrounding Area', '["S1201"]', 1, '2026-10-16 20:06:39'),
(13, 'vehicles@live.iium.edu.my', 'Express Campus Runner & Delivery Service', 'Fast on-demand delivery for food, parcels from campus mail hubs, groceries, and urgent errands straight to your Mahallah block.', 'service', 'Runner', 4.00, 'per_trip', 'IIUM Gombak Campus', '["S1301"]', 1, '2026-10-16 20:07:54'),
(14, 'gadget_fix@live.iium.edu.my', '24 Hours Gadget & Device Repair Service', 'Professional assistance in fixing damaged or malfunctioning items including smartphones, tablets, and laptops. Repairs of varying complexity available with 24-hour turnaround support.', 'service', 'Gadget Repair', 30.00, 'per_item', 'Mahallah Zaid Bin Harithah, IIUM Pagoh', '["S1401","S1402"]', 1, '2026-10-16 20:11:07'),
(15, 'soofun_print@live.iium.edu.my', 'Printing Service Sister (SooFun)', 'A4 printing services for students. B&W: RM0.20 (single) / RM0.30 (double-sided). Colour: RM0.50 (single) / RM0.70 (double-sided). Free pickup at Mahallah Asiah (Block F / MO) or COD delivery starting from RM2.00 depending on Mahallah.', 'service', 'Printing & Design', 0.20, 'per_item', 'Mahallah Asiah & COD Campus, IIUM Gombak', '["S1501","S1502"]', 1, '2026-10-16 20:12:39'),
(16, 'jey_barber@live.iium.edu.my', 'Jey Barber - Grooming & Haircut Services', 'On-campus haircut and grooming services. Menu: Full Haircut (RM10), Cut + Beard Trim (RM13), Hairline/Edge-Up (RM5), Beard & Mustache (RM4), Serum Styling (RM2), After-Hours/Custom Slot (RM15). Location: Room 2.4, Block D, Mahallah Salahuddin. Operating Hours: Daily 8:00 PM - 11:00 PM. Payment: Cash & DuitNow QR.', 'service', 'Barber & Grooming', 10.00, 'per_item', 'Room 2.4, Blok D, Mahallah Salahuddin, IIUM Gombak', '["S1601","S1602"]', 1, '2026-10-16 20:15:03'),
(17, 'peer_tutor@live.iium.edu.my', 'Peer Tutoring Service (Multi-Subject)', 'Comprehensive peer tutoring service for university students. Ready to teach Discrete Structure, Database Programming, or almost any subject required. One-on-one sessions or small group revisions available.', 'service', 'Tutoring', 25.00, 'per_hour', 'Dar al-Hikmah Library, IIUM Gombak/Online', '["S1701","S1702"]', 1, '2026-10-16 20:17:41'),
(18, 'express_ironing@live.iium.edu.my', 'Express Mahallah Ironing Service', 'Professional steam ironing and pressing services for formal wear, baju kurung, shirts, and trousers. Quick turnaround time with Mahallah pick-up and drop-off options available.', 'service', 'Laundry', 2.50, 'per_item', 'Mahallah Maimunah, IIUM Kuantan', '["S1801","S1802"]', 1, '2026-10-16 20:21:22');
